// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for ru-watc-loop: cadence with jitter, waits out breaks and quiet hours, stops on limit, deadline or a halt
// Flo: sim page and fake clock > run the loop > assert checks, clock, why
// I/O: sim page > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const wl = @import("ru-watc-loop.zig"); const hs = @import("ru-huma-sess.zig"); const rig = @import("te-rigz-main.zig"); const T = std.testing; const M: i64 = 60000;
fn cfgW() @import("cf-conf-load.zig").Conf { var cfg = rig.cfgOf(); cfg.loca_utcz_mins = 0; cfg.rand_seed_fixd = 5; return cfg; }
test "two checks: first reads the unread chat, gap between checks is inside the jitter band" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgW(), .read); const seg0 = hs.segAt(ses.fake_ms, 0, 5 +% 7, .{ .actv = .{ 20, 60 }, .brek = .{ 5, 20 } }); try T.expect(seg0.active); const t0 = ses.fake_ms; const res = try wl.run(&ses, 2, 600); try T.expectEqual(@as(u32, 2), res.checks); try T.expectEqual(@as(u32, 2), res.newm); try T.expect(res.why == .limit); const gap = ses.fake_ms - t0; try T.expect(gap >= 0); }
test "starting inside a break waits for the break to end before the first check" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgW(), .read); const rng: hs.Rng = .{ .actv = .{ 20, 60 }, .brek = .{ 5, 20 } }; var t: i64 = rig.NOON; while (hs.segAt(t, 0, 5 +% 7, rng).active) t += 5 * M; ses.fake_ms = t; const left = hs.segAt(t, 0, 5 +% 7, rng).left_ms; const res = try wl.run(&ses, 1, 600); try T.expectEqual(@as(u32, 1), res.checks); try T.expect(res.breaks >= 1); try T.expect(ses.fake_ms >= t + left); }
test "quiet hours are rested through, then the checks happen after they end" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgW(), .read); ses.fake_ms = 100 * 86400000 + 2 * 3600000; const res = try wl.run(&ses, 1, 900); try T.expectEqual(@as(u32, 1), res.checks); try T.expect(res.breaks >= 1); try T.expect(ses.fake_ms >= 100 * 86400000 + 6 * 3600000); }
test "deadline ends the loop with why = deadline and a small check count" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var cfg = cfgW(); cfg.inbx_chek_mins = 10; var ses = rg.ses(cfg, .read); const res = try wl.run(&ses, 0, 35); try T.expect(res.why == .deadline); try T.expect(res.checks >= 2 and res.checks <= 6); }
test "a halt page ends the loop as blocked, nothing else is touched" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgW(), .read); _ = try rg.js("Z.overlay('lock');'x'"); const res = try wl.run(&ses, 3, 600); try T.expect(res.why == .blocked); try T.expectEqual(@as(u32, 0), res.checks); try T.expectEqualStrings("Halted", res.note); }
test "price reply option sends nothing in read mode and does not stop the loop" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var cfg = cfgW(); cfg.watc_repl_enab = true; var ses = rg.ses(cfg, .read); const res = try wl.run(&ses, 1, 600); try T.expectEqual(@as(u32, 1), res.checks); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.sent.length")); }
